-- Step 49: a record of each file imported under Settings, Import data.
-- track: joint
--
-- The CREATE TABLE / constraint statements are generated by drizzle-kit from
-- src/modules/data-import/schema.ts. The section marked "hand-written" is not managed by
-- Drizzle. Reverse with the file of the same name in drizzle/down.
--
-- Why: a company coming from another system brings its customers, suppliers, items, opening
-- stock and opening balances in from files. The rows themselves go in through the commands that
-- already import each of them (nothing here writes a customer, an item, stock or a journal);
-- this table only remembers each import: what kind it was, the file's name and the SHA-256 of
-- its bytes, how many rows went in, and which heading of the file each of our columns was read
-- from. The import screen lists them as what has been imported so far, and offers a kind's last
-- mapping again for its next file. The app writes a row in the same transaction as the import
-- it records; nobody changes or removes one.
--
-- Who: the owner and an accountant import (they are the ones who open the books); the auditor
-- reads what was imported.

CREATE TABLE "data_imports" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"file_name" text NOT NULL,
	"file_sha256" text NOT NULL,
	"rows" integer NOT NULL,
	"mapping" jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" uuid NOT NULL,
	CONSTRAINT "data_imports_kind_known" CHECK ("data_imports"."kind" in ('customers', 'suppliers', 'items', 'opening_stock', 'customer_balances', 'supplier_balances', 'ledger_balances')),
	CONSTRAINT "data_imports_file_named" CHECK (length(btrim("data_imports"."file_name")) between 1 and 200),
	CONSTRAINT "data_imports_sha256" CHECK ("data_imports"."file_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "data_imports_rows" CHECK ("data_imports"."rows" > 0),
	CONSTRAINT "data_imports_mapping_object" CHECK (jsonb_typeof("data_imports"."mapping") = 'object')
);
--> statement-breakpoint
