-- Written by whoever imported, as themselves; there is no update or delete.
CREATE POLICY data_imports_insert ON public.data_imports FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant')
    AND created_by = (SELECT app.current_user_id())
  );
